@font-face {
  font-family: "T3 Claude Serif";
  src: url("data:font/woff;base64,") format("woff");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  unicode-range: U+0020-007E, U+00A0, U+00AB, U+00BB, U+2013-2014, U+2018-2019, U+201C-201D, U+2022, U+2026;
}

@font-face {
  font-family: "T3 Claude Serif";
  src: url("data:font/woff;base64,") format("woff");
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  unicode-range: U+0020-007E, U+00A0, U+00AB, U+00BB, U+2013-2014, U+2018-2019, U+201C-201D, U+2022, U+2026;
}

/* T3–Claude · classic Claude Desktop / Code surfaces.
 * Palette: Claude.app MainWindowPage CSS (2026-11-17). Anthropic Serif
 * subsets embedded at build; interface in Georgia.
 */
:root {
  --claude-font-serif: "T3 Claude Serif", "Anthropic Serif", Georgia,
    "Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", serif;
  --claude-font-interface: Georgia, "Songti SC", serif;
  --font-mono: "SFMono-Regular", "SF Mono", Menlo, Consolas, monospace;
  --surface-grain: none;
  --claude-radius: 8px;
}

/* Draft heroes live above the composer stack. Keep their shared width
 * independent of the Wide / Full transcript preference.
 */
html[data-theme-id="t3-claude"] [data-chat-composer-stack]:has(> div:first-child [data-draft-project-trigger], > div:first-child > div > div > h1) {
  max-width: min(100%, 46rem) !important;
}

html[data-theme-id="t3-claude"] [data-chat-composer-stack] > div:first-child:has([data-draft-project-trigger], > div > div > h1) {
  bottom: calc(100% - 24px) !important;
}

html[data-theme-id="t3-claude"] [data-chat-composer-stack] > div:first-child h1 {
  font-size: 1.75rem !important;
  line-height: 1.3 !important;
  text-wrap: balance;
}

@media (max-width: 640px), (max-height: 544px) {
  html[data-theme-id="t3-claude"] [data-chat-composer-stack] > div:first-child:has([data-draft-project-trigger], > div > div > h1) {
    bottom: calc(100% - 12px) !important;
  }

  html[data-theme-id="t3-claude"] [data-chat-composer-stack] > div:first-child h1 {
    font-size: 1.5rem !important;
  }
}

/* The CSS fallback plays complete source actions in place.
 * A JavaScript companion supplies walking, exact hit testing and gaze tracking.
 */
html[data-theme-id="t3-claude"] [data-slot="composer-shell"] {
  --clawd-lane-height: 80px;
  position: relative;
  padding-block-start: var(--clawd-lane-height) !important;
}

html[data-theme-id="t3-claude"] [data-slot="composer-shell"]::after {
  content: "";
  position: absolute;
  inset: auto 6px calc(100% - var(--clawd-lane-height)) auto;
  width: 96px;
  height: 80px;
  z-index: 1;
  background: var(--theme-background-image) -480px -160px / 3072px 1040px no-repeat;
  image-rendering: pixelated;
  pointer-events: auto;
  animation: t3-clawd-source-idle 120s steps(1, end) infinite, t3-clawd-source-stroll-x 120s linear infinite;
}

@media (hover: hover) and (pointer: fine) {
  html[data-theme-id="t3-claude"] [data-slot="composer-shell"]:hover:not(:has([data-slot="composer-host"]:hover))::after {
    animation: t3-clawd-source-wave 1.3333333333333333s steps(1, end) 1 forwards;
  }
}

html[data-theme-id="t3-claude"] [data-slot="composer-shell"][data-clawd-runtime]::after {
  content: none !important;
}

/* Hold still while the composer has focus, unless the agent is running:
 * then Clawd strolls first, then keeps the ambient schedule. */
html[data-theme-id="t3-claude"] [data-slot="composer-shell"]:focus-within:not(:has(button[aria-label="Stop generation"],button[aria-label="Stopping"],button[aria-label="Steer message"],button[aria-label="Queue message"],button[aria-label="Update queued message"]))::after {
  animation: none !important;
  background-position: -480px -160px !important;
}

html[data-theme-id="t3-claude"] [data-slot="composer-shell"]:has(button[aria-label="Stop generation"],button[aria-label="Stopping"],button[aria-label="Steer message"],button[aria-label="Queue message"],button[aria-label="Update queued message"])::after {
  animation-delay: -98s, -98s;
}

