body {
  font-family: var(--claude-font-interface);
  -webkit-font-smoothing: antialiased;
}

html[data-theme-id="t3-claude"] [data-slot="sidebar"],
html[data-theme-id="t3-claude"] [data-slot="sidebar-inner"] {
  background: var(--sidebar) !important;
  font-family: var(--claude-font-interface);
}

html[data-theme-id="t3-claude"] [data-thread-item] {
  border-radius: var(--claude-radius) !important;
}

html[data-theme-id="t3-claude"] [data-slot="project-monogram"] {
  border-radius: 6px !important;
  box-shadow: none !important;
}

html[data-theme-id="t3-claude"] [data-chat-header] {
  background: var(--background) !important;
  border-bottom-color: transparent !important;
  box-shadow: none !important;
  font-family: var(--claude-font-interface);
}

html[data-theme-id="t3-claude"] [data-workspace-area="conversation"] {
  background: var(--background) !important;
}

html[data-theme-id="t3-claude"] .messages-timeline-scroll {
  scrollbar-width: thin;
  scrollbar-color: var(--app-scrollbar-thumb, #aaa89e) transparent;
}

html[data-theme-id="t3-claude"] [data-user-message-bubble] {
  background: var(--message-surface) !important;
  color: var(--message-foreground) !important;
  border: 1px solid transparent !important;
  border-radius: 12px !important;
  padding: 12px 16px !important;
  box-shadow: none !important;
  font-family: var(--claude-font-serif);
  font-size: 15px;
  line-height: 1.7;
}

html[data-theme-id="t3-claude"] [data-message-role="user"] .chat-markdown,
html[data-theme-id="t3-claude"] [data-message-role="assistant"] .chat-markdown,
html[data-theme-id="t3-claude"] .composer-tiptap {
  font-family: var(--claude-font-serif) !important;
  font-size: 15px;
  line-height: 1.7;
  letter-spacing: normal;
  color: var(--foreground);
}

html[data-theme-id="t3-claude"] .chat-markdown :is(h1, h2, h3, h4) {
  font-family: var(--claude-font-serif);
  font-weight: 600;
  letter-spacing: -0.015em;
}

html[data-theme-id="t3-claude"] .chat-markdown :is(pre, code),
html[data-theme-id="t3-claude"] .composer-tiptap code,
html[data-theme-id="t3-claude"] kbd {
  font-family: var(--font-mono);
  font-variant-ligatures: none;
}

html[data-theme-id="t3-claude"] .chat-markdown-codeblock {
  border: 1px solid var(--border) !important;
  border-radius: var(--claude-radius) !important;
  box-shadow: none !important;
}

html[data-theme-id="t3-claude"] .chat-markdown pre {
  line-height: 1.6;
  font-size: 13px;
}

html[data-theme-id="t3-claude"] .chat-markdown :not(pre) > code {
  background: var(--secondary);
  padding: 0.12em 0.3em;
  border-radius: 4px;
  font-size: 0.88em;
}

html[data-theme-id="t3-claude"] [data-timeline-row-kind="work"] {
  font-family: var(--claude-font-serif);
  font-size: 13px;
}

/* Host owns the visible border. T3's glass and overlay outlines would
 * otherwise draw additional contours with their original 16px radius.
 */
html[data-theme-id="t3-claude"] [data-chat-composer-form] {
  --chat-composer-outline: transparent !important;
  --chat-composer-highlight: transparent !important;
}

html[data-theme-id="t3-claude"] [data-slot="composer-shell"],
html[data-theme-id="t3-claude"] [data-chat-composer-main-surface] {
  border: 0 !important;
  border-radius: 20px !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

html[data-theme-id="t3-claude"] [data-chat-composer-main-surface] {
  padding: 0 !important;
}

html[data-theme-id="t3-claude"] [data-slot="composer-shell"]::before,
html[data-theme-id="t3-claude"] [data-slot="composer-host"]::before,
html[data-theme-id="t3-claude"] [data-slot="composer-host"]::after,
html[data-theme-id="t3-claude"] [data-chat-composer-main-surface]::before,
html[data-theme-id="t3-claude"] [data-chat-composer-main-surface]::after {
  content: none !important;
}

html[data-theme-id="t3-claude"] [data-slot="composer-host"] {
  background: var(--surface-raised) !important;
  border: 1px solid var(--border) !important;
  border-radius: 20px !important;
  box-shadow: 0 2px 8px rgb(20 20 19 / 4%) !important;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

html[data-theme-id="t3-claude"] [data-slot="composer-host"]:focus-within {
  border-color: color-mix(in srgb, var(--foreground) 26%, var(--background)) !important;
  box-shadow: 0 2px 10px rgb(20 20 19 / 6%) !important;
}

html[data-theme-id="t3-claude"] [data-slot="button"] {
  border-radius: var(--claude-radius);
  font-family: var(--claude-font-interface);
  font-weight: 400;
}

html[data-theme-id="t3-claude"] [data-chat-composer-form] button[type="submit"] {
  background: var(--message-action, #d97757) !important;
  color: var(--primary-foreground) !important;
  border: 1px solid transparent !important;
  border-radius: var(--claude-radius) !important;
}

/* Send glyph: up arrow empty, return typing. Sprite: top arrow,
 * bottom return. Hover clay on both.
 */
html[data-theme-id="t3-claude"] [data-chat-composer-form] button[aria-label="Submit message"] {
  background: transparent !important;
  color: var(--muted-foreground) !important;
  box-shadow: none !important;
  pointer-events: auto;

  & > svg {
    display: none;
  }

  &::after {
    content: "";
    width: 16px;
    height: 16px;
    background: currentColor;
    mask: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 32' fill='none' stroke='black' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M8 13V3M3.6 7.4 8 3l4.4 4.4M13.3 18.7v4.6a2.7 2.7 0 0 1-2.6 2.7H2.7M6 22.7 2.7 26 6 29.3'/%3E%3C/svg%3E") no-repeat;
    mask-size: 100% 200%;
  }

  &:not(:disabled) {
    color: var(--foreground) !important;
  }

  &:not(:disabled)::after {
    mask-position: 0 100%;
  }

  &:hover {
    background: var(--message-action, #d97757) !important;
    color: var(--primary-foreground) !important;
  }
}

html[data-theme-id="t3-claude"] [aria-label="Stop generation"],
html[data-theme-id="t3-claude"] [aria-label="Stopping"] {
  background: var(--message-action, #d97757) !important;
}

html[data-theme-id="t3-claude"] :is(
  [data-slot="input"],
  [data-slot="select-trigger"]
) {
  border-radius: var(--claude-radius);
  font-family: var(--claude-font-interface);
}

html[data-theme-id="t3-claude"] :is(
  [data-slot="dialog-popup"],
  [data-slot="popover-popup"],
  [data-slot="menu-popup"]
) {
  border: 1px solid var(--border) !important;
  border-radius: 12px !important;
  background: var(--popover) !important;
  font-family: var(--claude-font-interface);
  box-shadow: 0 4px 24px rgb(20 20 19 / 12%) !important;
}

html[data-theme-id="t3-claude"] [data-slot="tooltip-popup"] {
  border-radius: 6px !important;
  font-family: var(--claude-font-interface);
}

html[data-theme-id="t3-claude"] [data-thread-details-card] {
  border: 1px solid var(--border) !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}

html[data-theme-id="t3-claude"] [data-thread-terminal-drawer] {
  background: var(--terminal-background) !important;
  border-color: var(--border) !important;
}

html[data-theme-id="t3-claude"] svg.lucide {
  stroke-width: 1.65px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

html[data-theme-id="t3-claude"] [data-slot="scroll-area-thumb"] {
  background: var(--app-scrollbar-thumb, #aaa89e) !important;
  border-radius: 999px;
}

html[data-theme-id="t3-claude"] ::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

html[data-theme-id="t3-claude"] ::-webkit-scrollbar-thumb {
  background: var(--app-scrollbar-thumb, #aaa89e);
  border: 2px solid transparent;
  border-radius: 999px;
  background-clip: padding-box;
}

html[data-theme-id="t3-claude"] ::-webkit-scrollbar-thumb:hover {
  background-color: var(--app-scrollbar-thumb-hover, #828078);
}

@media (prefers-reduced-motion: reduce) {
  html[data-theme-id="t3-claude"] [data-slot="composer-shell"]::after,
  html[data-theme-id="t3-claude"] [data-slot="composer-shell"]:hover::after {
    animation: none !important;
    background-position: -480px -160px !important;
  }

  html[data-theme-id="t3-claude"] [data-slot="composer-host"] {
    transition: none;
  }
}
